<?php
$monthly = $pdo->query("SELECT DATE_FORMAT(payment_date,'%b %Y') AS label,DATE_FORMAT(payment_date,'%Y-%m') AS sort_key,SUM(amount) AS total FROM payments WHERE payment_date>=DATE_SUB(CURDATE(),INTERVAL 11 MONTH) GROUP BY sort_key,label ORDER BY sort_key")->fetchAll();
$monthlyPatients = $pdo->query("SELECT DATE_FORMAT(registration_date,'%b %Y') AS label,DATE_FORMAT(registration_date,'%Y-%m') AS sort_key,COUNT(*) AS total FROM patients WHERE registration_date>=DATE_SUB(CURDATE(),INTERVAL 11 MONTH) GROUP BY sort_key,label ORDER BY sort_key")->fetchAll();
$deptStats = $pdo->query('SELECT d.name,COUNT(p.id) AS total FROM departments d LEFT JOIN patients p ON p.department_id=d.id GROUP BY d.id,d.name ORDER BY total DESC')->fetchAll();
$apptStats = $pdo->query("SELECT status,COUNT(*) AS total FROM appointments WHERE appointment_date>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) GROUP BY status")->fetchAll();
$stockStats = $pdo->query('SELECT medicine_name,quantity,low_stock_threshold FROM medicines ORDER BY quantity ASC LIMIT 10')->fetchAll();
$canSeeFinance = in_array(current_user()['role_name'],['super_admin','hospital_admin','accountant'],true);
$income = $canSeeFinance ? (float)$pdo->query('SELECT COALESCE(SUM(amount),0) FROM payments WHERE YEAR(payment_date)=YEAR(CURDATE()) AND MONTH(payment_date)=MONTH(CURDATE())')->fetchColumn() : null;
$pending = $canSeeFinance ? (float)$pdo->query("SELECT COALESCE(SUM(balance),0) FROM bills WHERE status<>'Paid'")->fetchColumn() : null;
?>
<div class="page-heading"><div><span class="eyebrow text-primary">INSIGHTS & PERFORMANCE</span><h1>Reports & analytics</h1><p>Monitor hospital activity, service demand and key operational trends.</p></div><div class="heading-actions"><button class="btn btn-outline-primary" onclick="window.print()"><i class="fa-solid fa-print me-2"></i>Print report</button></div></div>
<?php if($canSeeFinance): ?><div class="report-kpis"><div class="report-kpi"><small>Month-to-date collection</small><strong><?= money($income) ?></strong><span><i class="fa-solid fa-indian-rupee-sign"></i> Payments received this month</span></div><div class="report-kpi"><small>Outstanding receivables</small><strong><?= money($pending) ?></strong><span><i class="fa-solid fa-hourglass-half"></i> Pending and partial bills</span></div><div class="report-kpi"><small>Patient registrations</small><strong><?= (int)$pdo->query("SELECT COUNT(*) FROM patients WHERE MONTH(registration_date)=MONTH(CURDATE()) AND YEAR(registration_date)=YEAR(CURDATE())")->fetchColumn() ?></strong><span><i class="fa-solid fa-user-plus"></i> Current month</span></div></div><?php endif; ?>
<div class="row g-4"><div class="col-xl-7"><section class="panel-card"><div class="panel-header"><div><h3><?= $canSeeFinance ? 'Monthly collections' : 'Monthly patient registrations' ?></h3><p>12-month trend</p></div></div><div class="chart-wrap report-chart"><canvas id="mainReportChart"></canvas></div></section></div><div class="col-xl-5"><section class="panel-card"><div class="panel-header"><div><h3>Appointment outcomes</h3><p>Last 30 days</p></div></div><div class="chart-wrap report-chart"><canvas id="appointmentReportChart"></canvas></div></section></div><div class="col-xl-6"><section class="panel-card"><div class="panel-header"><div><h3>Department-wise patients</h3><p>All registered patients by assigned department</p></div></div><div class="table-responsive"><table class="table app-table"><thead><tr><th>Department</th><th>Patients</th><th>Share</th></tr></thead><tbody><?php $allDept=array_sum(array_map('intval',array_column($deptStats,'total'))); foreach($deptStats as $d): ?><tr><td><?= e($d['name']) ?></td><td><?= (int)$d['total'] ?></td><td><div class="progress slim-progress"><div class="progress-bar" style="width:<?= $allDept ? round(((int)$d['total']/$allDept)*100) : 0 ?>%"></div></div><small class="text-muted"><?= $allDept ? round(((int)$d['total']/$allDept)*100) : 0 ?>%</small></td></tr><?php endforeach; ?></tbody></table></div></section></div><div class="col-xl-6"><section class="panel-card"><div class="panel-header"><div><h3>Medicine stock snapshot</h3><p>Lowest quantity items</p></div><a class="text-link" href="<?= e(url('index.php?page=medicines')) ?>">Manage stock <i class="fa-solid fa-arrow-right ms-1"></i></a></div><div class="table-responsive"><table class="table app-table"><thead><tr><th>Medicine</th><th>Stock</th><th>Reorder level</th><th>Indicator</th></tr></thead><tbody><?php foreach($stockStats as $m): ?><tr><td><?= e($m['medicine_name']) ?></td><td><?= (int)$m['quantity'] ?></td><td><?= (int)$m['low_stock_threshold'] ?></td><td><span class="mini-tag <?= (int)$m['quantity'] <= (int)$m['low_stock_threshold'] ? 'warning':'success' ?>"><?= (int)$m['quantity'] <= (int)$m['low_stock_threshold'] ? 'Reorder':'Healthy' ?></span></td></tr><?php endforeach; ?></tbody></table></div></section></div></div>
<script>
const mainLabels = <?= json_encode(array_column($canSeeFinance ? $monthly : $monthlyPatients,'label')) ?>;
const mainValues = <?= json_encode(array_map('floatval',array_column($canSeeFinance ? $monthly : $monthlyPatients,'total'))) ?>;
const apptLabels = <?= json_encode(array_column($apptStats,'status')) ?>;
const apptValues = <?= json_encode(array_map('intval',array_column($apptStats,'total'))) ?>;
if(window.Chart){new Chart(document.getElementById('mainReportChart'),{type:'bar',data:{labels:mainLabels,datasets:[{data:mainValues,label:<?= json_encode($canSeeFinance?'Collections':'Patients') ?>,backgroundColor:'#4f9ce6',borderRadius:7,maxBarThickness:32}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,grid:{color:'#edf1f7'}},x:{grid:{display:false}}}}});new Chart(document.getElementById('appointmentReportChart'),{type:'doughnut',data:{labels:apptLabels,datasets:[{data:apptValues,backgroundColor:['#23b8a8','#438fe0','#9a83e7','#ef8895','#ffb454'],borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,cutout:'65%',plugins:{legend:{position:'bottom',labels:{usePointStyle:true,padding:16}}}}});}
</script>
